SPEC.E2=function(p){
  var s=[bg(C.sage)].concat(chrome(p),[T('Why teams choose Magoya',{x:7.5,y:11.5,w:70,h:7,s:4.4,b:true,tight:true})]);
  var g=[{h:'Domain expertise',l:['We work only in agribusiness, and have since 2017.','Agronomists sitting next to engineers.','Fluency with grower and retail workflows.']},
         {h:'Proven methodology',l:['A collaborative path from discovery to launch.','Senior pods assembled around your product.','Results that outlast the roadmap.']}];
  g.forEach(function(c,i){var x=7.5+i*43.5,y=21,w=41.5,h=28.2;
    s.push(card(x,y,w,h,C.w,C.hair));
    s.push(T(c.h,{x:x+2.2,y:y+2.2,w:w-4.4,h:4,s:2.1,b:true,tight:true}));
    c.l.forEach(function(t,j){s=s.concat(checkLine(x+2.2,y+8+j*5.6,w-4.4,t));});});
  return s;};

SPEC.E3=function(p){
  var s=[bg(C.w)].concat(chrome(p),[
    T('Two ways to staff this',{x:7.5,y:11.5,w:46,h:7,s:4,b:true,tight:true})],
    chip(70,12,'Scenario 1 of 2 · scope',C.em7,22.5));
  var rows=[[{text:'Role in the pod'},{text:'Lean'},{text:'Recommended'},{text:'What changes'}],
    ['Engagement lead','0.2','0.5','Weekly steering instead of monthly.'],
    ['Product designer','0.5','1.0','Field research runs in parallel with build.'],
    ['Senior engineers','2.0','3.0','Two workstreams instead of one queue.'],
    ['Data & AI engineer','—','1.0','Agronomic models enter the MVP, not phase 2.'],
    ['Agronomist','0.2','0.5','Validation on real operations every sprint.'],
    ['QA','0.3','0.5','Regression coverage before each season.'],
    ['Total FTE','3.2','6.5','Recommended halves time-to-field.']];
  var trows=rows.map(function(r,i){
    var head=i===0,tot=i===rows.length-1;
    return r.map(function(cell,j){
      var txt=(typeof cell==='object')?cell.text:cell;
      return {text:txt,options:{
        bold:head||tot||j===0,fontSize:FS(head?1.2:(tot?1.7:1.5)),
        color:head?C.g600:C.ink,align:(j===1||j===2)?'center':'left',
        fill:(j===2)?(tot?C.lime:C.sage):undefined,
        valign:'middle',margin:[6,8,6,8]}};});});
  s.push({k:'tb',x:7.5,y:21,w:85,rows:trows,
    opts:{colW:[IN(26),IN(11),IN(15),IN(33)],rowH:IN(3.9),
      border:[{type:'none'},{type:'none'},{type:'solid',color:C.hair,pt:.5},{type:'none'}]}});
  return s;};

SPEC.E4=function(p){
  var s=[bg(C.w)].concat(chrome(p),[
    T('Timing and investment',{x:7.5,y:11.5,w:46,h:7,s:4,b:true,tight:true})],
    chip(69,12,'Scenario 2 of 2 · numbers',C.em7,23.5));
  var d=[{h:'Lean',f:'3.2 FTE',n:[['9','months to MVP'],['1','workstream'],['Q3','first field season']],ft:'Phase 2 required for data & AI',dk:0},
         {h:'Recommended',f:'6.5 FTE',n:[['5','months to MVP'],['2','workstreams'],['Q1','first field season']],ft:'Data & AI included from sprint 1',dk:1}];
  d.forEach(function(c,i){var x=7.5+i*43.5,y=20.5,w=41.5,h=17.5;
    s.push(card(x,y,w,h,c.dk?C.g900:C.sage,null));
    s.push(T(c.h,{x:x+2.2,y:y+2,w:24,h:4,s:2.1,b:true,tight:true,c:c.dk?C.cr50:C.ink}));
    s.push(T(c.f,{x:x+w-14,y:y+2.6,w:12,h:3,s:1.45,c:c.dk?C.cr300:C.g600,al:'right'}));
    c.n.forEach(function(v,j){var vx=x+2.2+j*12.6;
      s.push(T(v[0],{x:vx,y:y+7.6,w:12,h:4,s:3.4,b:true,tight:true,c:c.dk?C.cr50:C.ink}));
      s.push(T(v[1],{x:vx,y:y+11.6,w:11.5,h:3.5,s:1.2,c:c.dk?C.cr300:C.g600,lh:1.2}));});
    s.push(T(c.ft,{x:x+2.2,y:y+h-3.2,w:w-4.4,h:2.6,s:1.4,b:true,c:c.dk?C.lime:C.ink}));});
  return s.concat(timeline(7.5,42,85,[{b:'Kick-off',s:'Week 0'},{b:'Discovery closed',s:'Week 6'},
    {b:'MVP in the field',s:'Month 5 · recommended'},{b:'MVP in the field',s:'Month 9 · lean'},
    {b:'Season review',s:'Month 12'}],2));};

